begin;
alter table public.orbit_comment_votes add column value smallint not null default 1 check(value in (-1,1));
alter table public.orbit_messages add column read boolean not null default false;
create table public.orbit_saved_comments(actor uuid references public.orbit_profiles(id) on delete cascade,comment bigint references public.orbit_comments(id) on delete cascade,created timestamptz not null default now(),primary key(actor,comment));
create index orbit_saved_comments_comment on public.orbit_saved_comments(comment);
create table public.orbit_reposts(actor uuid references public.orbit_profiles(id) on delete cascade,post bigint references public.orbit_posts(id) on delete cascade,created timestamptz not null default now(),primary key(actor,post));
create index orbit_reposts_post on public.orbit_reposts(post);
create table public.orbit_post_awards(actor uuid references public.orbit_profiles(id) on delete cascade,post bigint references public.orbit_posts(id) on delete cascade,kind text not null check(kind in ('Helpful','Insightful','Campus spirit')),created timestamptz not null default now(),primary key(actor,post));
create index orbit_post_awards_post on public.orbit_post_awards(post);
create table public.orbit_content_reports(id bigint generated by default as identity primary key,reporter uuid not null references public.orbit_profiles(id) on delete cascade,post bigint not null references public.orbit_posts(id) on delete cascade,comment bigint references public.orbit_comments(id) on delete cascade,reason text not null check(reason in ('Spam','Harassment','Impersonation','Other')),details text not null default '' check(length(details)<=1000),status text not null default 'open' check(status in ('open','resolved')),created timestamptz not null default now());
create unique index orbit_content_reports_unique on public.orbit_content_reports(reporter,post,(coalesce(comment,0)));
create index orbit_content_reports_post on public.orbit_content_reports(post);
create index orbit_content_reports_comment on public.orbit_content_reports(comment);
create index orbit_messages_unread on public.orbit_messages(recipient,sender,id desc) where not read;
alter table public.orbit_saved_comments enable row level security;
alter table public.orbit_reposts enable row level security;
alter table public.orbit_post_awards enable row level security;
alter table public.orbit_content_reports enable row level security;
create policy saved_comments_own on public.orbit_saved_comments for select to authenticated using(actor=(select auth.uid()) and exists(select 1 from public.orbit_comments c where c.id=comment and orbit_private.can_read(c.post) and not orbit_private.blocked((select auth.uid()),c.author)));
create policy reposts_own on public.orbit_reposts for select to authenticated using(actor=(select auth.uid()) and orbit_private.can_read(post));
create policy awards_own on public.orbit_post_awards for select to authenticated using(actor=(select auth.uid()) and orbit_private.can_read(post));
create policy content_reports_moderator on public.orbit_content_reports for select to authenticated using((select orbit_private.platform_mod()));
revoke all on public.orbit_saved_comments,public.orbit_reposts,public.orbit_post_awards,public.orbit_content_reports from public,anon,authenticated;
grant select on public.orbit_saved_comments,public.orbit_reposts,public.orbit_post_awards,public.orbit_content_reports to authenticated;
grant all on public.orbit_saved_comments,public.orbit_reposts,public.orbit_post_awards,public.orbit_content_reports to service_role;
grant usage,select on sequence public.orbit_content_reports_id_seq to service_role;
create function orbit_private.comment_meta(cid bigint) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare c public.orbit_comments;u uuid:=auth.uid();up integer;down integer;own integer;begin
 select * into c from public.orbit_comments where id=cid;if c.id is null or not orbit_private.can_read(c.post) or orbit_private.blocked(u,c.author) then return null;end if;
 select count(*) filter(where value=1),count(*) filter(where value=-1),coalesce(max(value) filter(where actor=u),0) into up,down,own from public.orbit_comment_votes where comment=cid;
 return jsonb_build_object('likes',up,'liked',own=1,'disliked',own=-1,'bestScore',up-down,'controversy',case when up+down=0 then 0 else ln(1+up+down)*(1-abs(up-down)::numeric/(up+down)) end,'saved',exists(select 1 from public.orbit_saved_comments where actor=u and comment=cid));end;$$;
create function orbit_private.post_meta(pid bigint) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p public.orbit_posts;u uuid:=auth.uid();begin
 select * into p from public.orbit_posts where id=pid;if not orbit_private.can_read(pid) then return null;end if;
 return jsonb_build_object('following',exists(select 1 from public.orbit_follows where actor=u and target=p.author),'reposted',exists(select 1 from public.orbit_reposts where actor=u and post=pid),'repostCount',(select count(*) from public.orbit_reposts where post=pid),'myAward',(select kind from public.orbit_post_awards where actor=u and post=pid),'awards',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from(select kind,count(*) as count from public.orbit_post_awards where post=pid group by kind)a),'repostedBy',(select coalesce(jsonb_agg(r.handle),'[]') from(select profile.handle from public.orbit_reposts rp join public.orbit_profiles profile on profile.id=rp.actor where rp.post=pid and not orbit_private.blocked(u,rp.actor) order by rp.created desc limit 3)r));end;$$;
create function orbit_private.report_content(pid bigint,cid bigint,reason text,details text) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=orbit_private.actor();begin
 if not orbit_private.can_read(pid) or cid is not null and not exists(select 1 from public.orbit_comments where id=cid and post=pid and not deleted and not orbit_private.blocked(u,author)) then raise exception 'Contribution unavailable.' using errcode='42501';end if;
 insert into public.orbit_content_reports(reporter,post,comment,reason,details) values(u,pid,cid,reason,coalesce(details,'')) on conflict(reporter,post,(coalesce(comment,0))) do update set reason=excluded.reason,details=excluded.details,status='open';end;$$;
revoke all on function orbit_private.comment_meta(bigint),orbit_private.post_meta(bigint),orbit_private.report_content(bigint,bigint,text,text) from public,anon,authenticated;
grant execute on function orbit_private.comment_meta(bigint),orbit_private.post_meta(bigint) to anon,authenticated,service_role;
grant execute on function orbit_private.report_content(bigint,bigint,text,text) to service_role;
create or replace function orbit_private.api(path text,method text,body jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();peer uuid;parts text[]:=string_to_array(trim(both '/' from path),'/');lim integer:=least(50,greatest(1,coalesce((body->>'limit')::integer,25)));before_id bigint:=coalesce((body->>'before')::bigint,9223372036854775807);pid bigint;cid bigint;rid bigint;rowp public.orbit_posts;rowc public.orbit_comments;circle_row public.orbit_circles;conn public.orbit_connections;result jsonb;val text;exists_vote boolean;begin
 if jsonb_typeof(body)<>'object' or method not in ('GET','POST') then raise exception 'Invalid request.';end if;
 if method='POST' then u:=orbit_private.actor();perform orbit_private.rate_actor(u);end if;
 if path='/me' and method='GET' then select jsonb_build_object('user',case when p.id is null then null else jsonb_build_object('id',p.id,'handle',p.handle,'displayName',p.display_name,'bio',p.bio,'university',p.university,'campus',p.campus,'isModerator',orbit_private.platform_mod()) end) into result from (select u as id) current_user_id left join public.orbit_profiles p using(id);return result;end if;
 if path='/profile' and method='POST' then update public.orbit_profiles set display_name=trim(body->>'displayName'),bio=coalesce(body->>'bio',''),university=coalesce(body->>'university',''),campus=coalesce(body->>'campus','') where id=u;return orbit_private.api('/me','GET','{}')->'user';end if;
 if path='/profiles' and method='GET' then select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select id,handle,display_name as "displayName",bio,university,campus from public.orbit_profiles where (coalesce(body->>'q','')='' or display_name ilike '%'||(body->>'q')||'%' or handle ilike '%'||(body->>'q')||'%') and (coalesce(body->>'campus','')='' or campus=body->>'campus') and not orbit_private.blocked(u,id) order by handle limit lim) p;return jsonb_build_object('items',result);end if;
 if path='/inbox' and method='GET' then u:=orbit_private.actor();
 select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select p.id,p.handle,p.display_name as "displayName",recent.id as message_id,recent.text,recent.created,recent.outgoing,recent.unread,exists(select 1 from public.orbit_connections cn where cn.low_actor=least(u,p.id) and cn.high_actor=greatest(u,p.id) and cn.status='accepted') as connected from(select distinct on(m.peer) m.peer,m.id,m.text,m.created,(m.sender=u) as outgoing,sum(case when m.recipient=u and not m.read then 1 else 0 end) over(partition by m.peer) as unread from(select m.*,case when sender=u then recipient else sender end as peer from public.orbit_messages m where (sender=u or recipient=u))m order by m.peer,m.id desc)recent join public.orbit_profiles p on p.id=recent.peer where not orbit_private.blocked(u,p.id) and recent.id<before_id order by recent.id desc limit lim)r;return jsonb_build_object('items',result,'next',result->-1->'message_id');end if;
 if path='/contacts' and method='GET' then u:=orbit_private.actor();select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select p.id,p.handle,p.display_name as "displayName" from public.orbit_profiles p join public.orbit_connections c on p.id=case when c.sender=u then c.recipient else c.sender end where (c.sender=u or c.recipient=u) and c.status='accepted' and (coalesce(body->>'q','')='' or p.display_name ilike '%'||(body->>'q')||'%' or p.handle ilike '%'||(body->>'q')||'%') and not orbit_private.blocked(u,p.id) order by p.handle limit lim)p;return jsonb_build_object('items',result);end if;
 if path='/saved-comments' and method='GET' then u:=orbit_private.actor();select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select c.*,p.handle,p.display_name as "displayName",post.title as "postTitle",orbit_private.comment_meta(c.id) as interactions from public.orbit_saved_comments s join public.orbit_comments c on c.id=s.comment join public.orbit_posts post on post.id=c.post join public.orbit_profiles p on p.id=c.author where s.actor=u and c.id<before_id and orbit_private.can_read(c.post) and not orbit_private.blocked(u,c.author) order by c.id desc limit lim)r;return jsonb_build_object('items',result);end if;
 if path='/content-reports' and method='GET' then u:=orbit_private.actor();if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select * from public.orbit_content_reports where id<before_id order by id desc limit lim)r;return jsonb_build_object('items',result);end if;
 if parts[1]='content-reports' and method='POST' then if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;update public.orbit_content_reports set status=body->>'status' where id=parts[2]::bigint;return '{"ok":true}';end if;
 if parts[1]='messages' and parts[3]='read' and method='POST' then select id into peer from public.orbit_profiles where handle=parts[2];if peer is null or orbit_private.blocked(u,peer) then raise exception 'Conversation unavailable.' using errcode='42501';end if;update public.orbit_messages set read=true where recipient=u and sender=peer;return '{"ok":true}';end if;
 if path='/events' and method='GET' then select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select post.*,orbit_private.post_meta(post.id) as interactions,profile.display_name as "displayName",profile.handle,profile.university,profile.campus,(select title from public.orbit_circles where id=post.circle) as "circleTitle",coalesce((select private from public.orbit_circles where id=post.circle),false) as "circlePrivate",exists(select 1 from public.orbit_votes where actor=u and public.orbit_votes.post=post.id) as voted,exists(select 1 from public.orbit_saved_posts saved where saved.actor=u and saved.post=post.id) as saved,(select coalesce(jsonb_agg(to_jsonb(preview)),'[]') from(select c.id,c.text,c.author,p.handle,c.upvotes,c.created from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.post=post.id and (c.parent is null or c.id=post.best_answer) and not c.deleted and not orbit_private.blocked(u,c.author) order by (c.id=post.best_answer) desc nulls last,c.upvotes desc,c.id desc limit 2)preview) as preview from public.orbit_posts post join public.orbit_profiles profile on profile.id=post.author where post.event_at>=now() and orbit_private.can_read(post.id) and (post.circle is null or exists(select 1 from public.orbit_circles c where c.id=post.circle and not c.private)) and (coalesce(body->>'university','')='' or profile.university=body->>'university') and (coalesce(body->>'campus','')='' or profile.campus=body->>'campus') order by post.event_at,post.id limit lim)p;return jsonb_build_object('items',result);end if;
 if path='/feed' and method='GET' then
 if body->>'circle' is not null and not exists(select 1 from public.orbit_circles where id=(body->>'circle')::bigint and (not private or orbit_private.member(id))) then raise exception 'Circle unavailable.' using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select post.*,orbit_private.post_meta(post.id) as interactions,profile.display_name as "displayName",profile.handle,profile.university,profile.campus,(select title from public.orbit_circles where id=post.circle) as "circleTitle",coalesce((select private from public.orbit_circles where id=post.circle),false) as "circlePrivate",exists(select 1 from public.orbit_votes where actor=u and public.orbit_votes.post=post.id) as voted,exists(select 1 from public.orbit_saved_posts saved where saved.actor=u and saved.post=post.id) as saved,(select coalesce(jsonb_agg(to_jsonb(preview)),'[]') from(select c.id,c.text,c.author,p.handle,c.upvotes,c.created from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.post=post.id and (c.parent is null or c.id=post.best_answer) and not c.deleted and not orbit_private.blocked(u,c.author) order by (c.id=post.best_answer) desc nulls last,c.upvotes desc,c.id desc limit 2)preview) as preview from public.orbit_posts post join public.orbit_profiles profile on profile.id=post.author where (body->>'sort' in ('Hot','Top') or post.id<before_id) and orbit_private.can_read(post.id) and (body->>'circle' is null or post.circle=(body->>'circle')::bigint) and (coalesce(body->>'q','')='' or post.title ilike '%'||(body->>'q')||'%' or post.text ilike '%'||(body->>'q')||'%') and (body->>'author' is null or post.author=(body->>'author')::uuid or exists(select 1 from public.orbit_reposts rp where rp.post=post.id and rp.actor=(body->>'author')::uuid))
 and (body->>'public' is distinct from 'true' or post.circle is null or exists(select 1 from public.orbit_circles c where c.id=post.circle and not c.private)) and (coalesce(body->>'university','')='' or profile.university=body->>'university') and (coalesce(body->>'campus','')='' or profile.campus=body->>'campus')
 and (coalesce(body->>'topic','')='' or post.topic=body->>'topic') and (coalesce(body->>'purpose','')='' or post.flair=body->>'purpose')
 and (body->>'following' is distinct from 'true' or exists(select 1 from public.orbit_follows f where f.actor=u and (f.target=post.author or exists(select 1 from public.orbit_reposts rp where rp.post=post.id and rp.actor=f.target))))
 and (body->>'saved' is distinct from 'true' or exists(select 1 from public.orbit_saved_posts s where s.actor=u and s.post=post.id)) order by case when body->>'sort'='Hot' then (post.upvotes+post.reply_count+1)/power(greatest(0,extract(epoch from(now()-post.created))/3600)+2,1.5) when body->>'sort'='Top' then post.upvotes::numeric when body->>'sort'='For you' then case when exists(select 1 from public.orbit_follows f where f.actor=u and f.target=post.author) then 1 else 0 end else 0 end desc,post.id desc limit lim offset least(10000,greatest(0,coalesce((body->>'offset')::integer,0)))) p;return jsonb_build_object('items',result,'next',result->-1->'id');end if;
 if path='/posts' and method='POST' then cid:=(body->>'circle')::bigint;if cid is not null then select * into circle_row from public.orbit_circles where id=cid;if circle_row.id is null or not orbit_private.member(cid) or orbit_private.blocked(u,circle_row.owner) then raise exception 'Circle membership required.' using errcode='42501';end if;end if;insert into public.orbit_posts(author,title,text,topic,circle,flair,event_at,event_place) values(u,trim(body->>'title'),trim(body->>'text'),coalesce(body->>'topic',''),cid,coalesce(body->>'flair','Discussion'),nullif(body->>'eventAt','')::timestamptz,coalesce(body->>'eventPlace','')) returning id into pid;return jsonb_build_object('id',pid);end if;
 if parts[1]='posts' and array_length(parts,1)>=2 then pid:=parts[2]::bigint;select * into rowp from public.orbit_posts where id=pid;if not orbit_private.can_read(pid) then raise exception 'Post unavailable.' using errcode='42501';end if;
 if array_length(parts,1)=2 and method='GET' then select to_jsonb(p) into result from(select post.*,orbit_private.post_meta(post.id) as interactions,profile.display_name as "displayName",profile.handle,profile.university,profile.campus,(select title from public.orbit_circles where id=post.circle) as "circleTitle",coalesce((select private from public.orbit_circles where id=post.circle),false) as "circlePrivate",exists(select 1 from public.orbit_votes where actor=u and post=post.id) as voted,exists(select 1 from public.orbit_saved_posts saved where saved.actor=u and saved.post=post.id) as saved,(select coalesce(jsonb_agg(to_jsonb(preview)),'[]') from(select c.id,c.text,c.author,p.handle,c.upvotes,c.created from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.post=post.id and (c.parent is null or c.id=post.best_answer) and not c.deleted and not orbit_private.blocked(u,c.author) order by (c.id=post.best_answer) desc nulls last,c.upvotes desc,c.id desc limit 2)preview) as preview from public.orbit_posts post join public.orbit_profiles profile on profile.id=post.author where post.id=pid)p;return result;end if;
 if parts[3]='repost' and method='POST' then if rowp.circle is not null and exists(select 1 from public.orbit_circles where id=rowp.circle and private) then raise exception 'Private-circle posts cannot be reposted.' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('repost:'||u::text||':'||pid::text,0));if exists(select 1 from public.orbit_reposts where actor=u and post=pid) then delete from public.orbit_reposts where actor=u and post=pid;else insert into public.orbit_reposts values(u,pid,now());end if;return '{"ok":true}';end if;
 if parts[3]='award' and method='POST' then if rowp.author=u then raise exception 'You cannot award your own post.';end if;perform pg_advisory_xact_lock(hashtextextended('award:'||u::text||':'||pid::text,0));if body->>'kind' is null then delete from public.orbit_post_awards where actor=u and post=pid;else insert into public.orbit_post_awards(actor,post,kind) values(u,pid,body->>'kind') on conflict(actor,post) do update set kind=excluded.kind;end if;return '{"ok":true}';end if;
 if parts[3]='report' and method='POST' then perform orbit_private.report_content(pid,null,body->>'reason',body->>'details');return '{"ok":true}';end if;
 if parts[3]='comment' and method='GET' then select to_jsonb(r) into result from(select c.*,p.handle,p.display_name as "displayName",orbit_private.comment_meta(c.id) as interactions from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.id=parts[4]::bigint and c.post=pid and not orbit_private.blocked(u,c.author))r;return result;end if;
 if parts[3]='save' and method='POST' then perform pg_advisory_xact_lock(hashtextextended('save:'||u::text||':'||pid::text,0));if exists(select 1 from public.orbit_saved_posts where actor=u and post=pid) then delete from public.orbit_saved_posts where actor=u and post=pid;else insert into public.orbit_saved_posts(actor,post) values(u,pid);end if;return '{"ok":true}';end if;
 if parts[3]='best' and method='POST' then perform pg_advisory_xact_lock(hashtextextended('answer:'||pid::text,0)); if rowp.author<>u or not(rowp.flair='Question' or rowp.topic='Questions') then raise exception 'Only the question author can accept an answer.' using errcode='42501';end if;rid:=(body->>'reply')::bigint;if rid is not null and not exists(select 1 from public.orbit_comments c where c.id=rid and c.post=pid and not c.deleted and c.author<>u and not orbit_private.blocked(u,c.author)) then raise exception 'Choose an available answer from another student.' using errcode='42501';end if;update public.orbit_posts set best_answer=rid where id=pid;return '{"ok":true}';end if;
 if array_length(parts,1)=2 and method='POST' then if rowp.author<>u then raise exception 'Only the author can change this post.' using errcode='42501';end if;if body->>'delete'='true' then update public.orbit_posts set title='Deleted post',text='[Deleted]',deleted=true,edited=now() where id=pid;else update public.orbit_posts set title=trim(body->>'title'),text=trim(body->>'text'),flair=coalesce(body->>'flair',flair),event_at=case when body?'eventAt' then nullif(body->>'eventAt','')::timestamptz else event_at end,event_place=case when body?'eventPlace' then coalesce(body->>'eventPlace','') else event_place end,edited=now() where id=pid;end if;return '{"ok":true}';end if;
 if parts[3]='accepted' and method='GET' then select to_jsonb(r) into result from(select c.*,p.handle,p.display_name as "displayName",orbit_private.comment_meta(c.id) as interactions,exists(select 1 from public.orbit_comment_votes v where v.comment=c.id and v.actor=u) as voted from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.id=rowp.best_answer and c.post=pid and not c.deleted and not orbit_private.blocked(u,c.author))r;return result;end if;
 if parts[3]='comments' and method='GET' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select c.*,p.handle,p.display_name as "displayName",orbit_private.comment_meta(c.id) as interactions,exists(select 1 from public.orbit_comment_votes v where v.comment=c.id and v.actor=u) as voted from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.post=pid and c.id<before_id and not orbit_private.blocked(u,c.author) order by c.id desc limit lim) r;return jsonb_build_object('items',result);end if;
 if parts[3]='comments' and method='POST' then rid:=(body->>'parent')::bigint;if rid is not null and not exists(select 1 from public.orbit_comments where id=rid and post=pid and not deleted and not orbit_private.blocked(u,author)) then raise exception 'Comment unavailable.';end if;insert into public.orbit_comments(post,author,parent,text) values(pid,u,rid,trim(body->>'text')) returning id into rid;update public.orbit_posts set reply_count=reply_count+1 where id=pid;perform orbit_private.notify(rowp.author,u,'reply',pid);return jsonb_build_object('id',rid);end if;
 if parts[3]='vote' and method='POST' then perform pg_advisory_xact_lock(hashtextextended('vote:'||u::text||':'||pid::text,0));exists_vote:=exists(select 1 from public.orbit_votes where post=pid and actor=u);if exists_vote then delete from public.orbit_votes where post=pid and actor=u;else insert into public.orbit_votes values(pid,u);perform orbit_private.notify(rowp.author,u,'upvote',pid);end if;update public.orbit_posts set upvotes=upvotes+case when exists_vote then -1 else 1 end where id=pid returning upvotes into rid;return jsonb_build_object('upvotes',rid);end if;end if;
 if parts[1]='comments' and parts[3] in ('react','vote','save','report') and method='POST' then select * into rowc from public.orbit_comments where id=parts[2]::bigint;if rowc.id is null or rowc.deleted or not orbit_private.can_read(rowc.post) or orbit_private.blocked(u,rowc.author) then raise exception 'Comment unavailable.' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('comment-vote:'||u::text||':'||rowc.id::text,0));
 if parts[3] in ('react','vote') then select value::text into val from public.orbit_comment_votes where actor=u and comment=rowc.id;if parts[3]='vote' then rid:=case when val='1' then 0 else 1 end;else rid:=(body->>'value')::integer;end if;if rid is null or rid not in (-1,0,1) then raise exception 'Choose like, dislike or no reaction.';end if;delete from public.orbit_comment_votes where actor=u and comment=rowc.id;if rid<>0 then insert into public.orbit_comment_votes(comment,actor,value) values(rowc.id,u,rid);end if;update public.orbit_comments set upvotes=greatest(0,upvotes-case when val='1' then 1 else 0 end+case when rid=1 then 1 else 0 end) where id=rowc.id;
 elsif parts[3]='save' then if exists(select 1 from public.orbit_saved_comments where actor=u and comment=rowc.id) then delete from public.orbit_saved_comments where actor=u and comment=rowc.id;else insert into public.orbit_saved_comments(actor,comment) values(u,rowc.id);end if;
 else perform orbit_private.report_content(rowc.post,rowc.id,body->>'reason',body->>'details');end if;return '{"ok":true}';end if;
 if parts[1]='comments' and method='POST' then select * into rowc from public.orbit_comments where id=parts[2]::bigint;if rowc.id is null or rowc.author<>u or rowc.deleted or not orbit_private.can_read(rowc.post) then raise exception 'Only the author can change this comment.' using errcode='42501';end if;if body->>'delete'='true' then perform pg_advisory_xact_lock(hashtextextended('answer:'||rowc.post::text,0));update public.orbit_comments set text='[Deleted]',deleted=true,edited=now() where id=rowc.id;update public.orbit_posts set best_answer=null where best_answer=rowc.id;update public.orbit_posts set reply_count=greatest(0,reply_count-1) where id=rowc.post;else update public.orbit_comments set text=trim(body->>'text'),edited=now() where id=rowc.id;end if;return '{"ok":true}';end if;
 if parts[1]='people' and array_length(parts,1)=3 then u:=orbit_private.actor();select id into peer from public.orbit_profiles where handle=parts[2];if peer is null or peer=u then raise exception 'Student unavailable.';end if;perform orbit_private.lock_pair(u,peer);
 if parts[3]='block' and method='POST' then if body->>'block'='false' then delete from public.orbit_blocks where actor=u and target=peer;else insert into public.orbit_blocks values(u,peer) on conflict do nothing;update public.orbit_connections set status='removed' where low_actor=least(u,peer) and high_actor=greatest(u,peer);perform orbit_private.cancel_games(u,peer);end if;return '{"ok":true}';end if;
 if orbit_private.blocked(u,peer) then raise exception 'Student unavailable.' using errcode='42501';end if;
 select * into conn from public.orbit_connections where low_actor=least(u,peer) and high_actor=greatest(u,peer);
 if method='GET' then return jsonb_build_object('connection',case when conn.sender is null then null else jsonb_build_object('sender',conn.sender,'recipient',conn.recipient,'status',conn.status) end,'following',exists(select 1 from public.orbit_follows where actor=u and target=peer),'peer',peer);end if;
 if parts[3]='follow' then if exists(select 1 from public.orbit_follows where actor=u and target=peer) then delete from public.orbit_follows where actor=u and target=peer;else insert into public.orbit_follows values(u,peer);perform orbit_private.notify(peer,u,'follow');end if;return '{"ok":true}';end if;
 if parts[3]='connection' then val:=body->>'action';if val='request' then if conn.status in ('pending','accepted') then raise exception 'Connection already exists.';end if;insert into public.orbit_connections(sender,recipient,status) values(u,peer,'pending') on conflict(low_actor,high_actor) do update set sender=excluded.sender,recipient=excluded.recipient,status='pending';perform orbit_private.notify(peer,u,'request');elsif val in ('accept','decline') then if conn.status is distinct from 'pending' or conn.recipient is distinct from u then raise exception 'Only the recipient can respond.' using errcode='42501';end if;update public.orbit_connections set status=case when val='accept' then 'accepted' else 'declined' end where low_actor=least(u,peer) and high_actor=greatest(u,peer);elsif val='remove' then if conn.status is distinct from 'accepted' then raise exception 'Connection unavailable.';end if;update public.orbit_connections set status='removed' where low_actor=least(u,peer) and high_actor=greatest(u,peer);perform orbit_private.cancel_games(u,peer);else raise exception 'Unknown connection action.';end if;return '{"ok":true}';end if;end if;
 if parts[1]='messages' and array_length(parts,1)=2 then u:=orbit_private.actor();select id into peer from public.orbit_profiles where handle=parts[2];if peer is null or peer=u or orbit_private.blocked(u,peer) then raise exception 'Conversation unavailable.' using errcode='42501';end if;
 if method='GET' then select coalesce(jsonb_agg(to_jsonb(m)),'[]') into result from(select m.*,p.handle from public.orbit_messages m join public.orbit_profiles p on p.id=m.sender where m.id<before_id and ((sender=u and recipient=peer) or(sender=peer and recipient=u)) order by m.id desc limit lim) m;return jsonb_build_object('items',result);end if;
 perform orbit_private.lock_pair(u,peer);if not exists(select 1 from public.orbit_connections where low_actor=least(u,peer) and high_actor=greatest(u,peer) and status='accepted') or orbit_private.blocked(u,peer) then raise exception 'An accepted connection is required.' using errcode='42501';end if;insert into public.orbit_messages(sender,recipient,text) values(u,peer,trim(body->>'text')) returning id into rid;perform orbit_private.notify(peer,u,'message',rid);return jsonb_build_object('id',rid);end if;
 if path='/circles' and method='GET' then select coalesce(jsonb_agg(to_jsonb(c)),'[]') into result from(select c.id,c.title,c.description,c.owner,c.private,c.rules,c.introduction,c.cover,case when orbit_private.can_read(c.pinned_post) then c.pinned_post else null end as pinned_post,(select coalesce(jsonb_agg(p.handle),'[]') from public.orbit_members m join public.orbit_profiles p on p.id=m.actor where m.circle=c.id and m.role in ('owner','moderator') and (not c.private or orbit_private.member(c.id) or m.role='owner')) as moderators,(select count(*) from public.orbit_members where circle=c.id) as "memberCount",(select handle from public.orbit_profiles where id=c.owner) as "ownerHandle",(select role from public.orbit_members where circle=c.id and actor=u) as role,exists(select 1 from public.orbit_join_requests j where j.circle=c.id and j.actor=u) as requested from public.orbit_circles c where c.id<before_id and (body->>'id' is null or c.id=(body->>'id')::bigint) and not orbit_private.blocked(u,c.owner) order by c.id desc limit lim)c;return jsonb_build_object('items',result);end if;
 if path='/circles' and method='POST' then insert into public.orbit_circles(title,description,owner,private) values(trim(body->>'title'),trim(body->>'description'),u,coalesce((body->>'private')::boolean,false)) returning id into cid;insert into public.orbit_members values(cid,u,'owner');return jsonb_build_object('id',cid);end if;
 if parts[1]='circles' and array_length(parts,1)=2 and method='GET' then return orbit_private.api('/circles','GET',jsonb_build_object('id',parts[2],'limit',1))->'items'->0;end if;
 if parts[1]='circles' and array_length(parts,1)=3 then u:=orbit_private.actor();cid:=parts[2]::bigint;select * into circle_row from public.orbit_circles where id=cid;if circle_row.id is null or orbit_private.blocked(u,circle_row.owner) then raise exception 'Circle unavailable.' using errcode='42501';end if;
 if parts[3]='members' and method='GET' then if not orbit_private.member(cid) then raise exception 'Membership required.' using errcode='42501';end if;return jsonb_build_object('members',(select coalesce(jsonb_agg(jsonb_build_object('user',p.handle,'id',m.actor,'role',m.role)),'[]') from public.orbit_members m join public.orbit_profiles p on p.id=m.actor where circle=cid),'requests',case when orbit_private.circle_mod(cid) then(select coalesce(jsonb_agg(jsonb_build_object('user',p.handle,'id',r.actor)),'[]') from public.orbit_join_requests r join public.orbit_profiles p on p.id=r.actor where circle=cid)else '[]'::jsonb end);end if;
 if method='POST' then if parts[3]='join' then if circle_row.private then insert into public.orbit_join_requests values(cid,u) on conflict do nothing;else insert into public.orbit_members values(cid,u,'member') on conflict do nothing;end if;
 elsif parts[3]='review' then if not orbit_private.circle_mod(cid) then raise exception 'Moderator required.' using errcode='42501';end if;select id into peer from public.orbit_profiles where handle=body->>'user';if peer is null or orbit_private.blocked(u,peer) or exists(select 1 from public.orbit_blocks where (actor=peer and target=circle_row.owner) or(actor=circle_row.owner and target=peer)) or not exists(select 1 from public.orbit_join_requests where circle=cid and actor=peer) then raise exception 'Request unavailable.';end if;if body->>'accept'='true' then insert into public.orbit_members values(cid,peer,'member') on conflict do nothing;end if;delete from public.orbit_join_requests where circle=cid and actor=peer;
 elsif parts[3]='moderator' then if circle_row.owner<>u then raise exception 'Owner required.' using errcode='42501';end if;select id into peer from public.orbit_profiles where handle=body->>'user';if peer is null or peer=u or not exists(select 1 from public.orbit_members where circle=cid and actor=peer) then raise exception 'Choose another member.';end if;update public.orbit_members set role=case when body->>'moderator'='true' then 'moderator' else 'member' end where circle=cid and actor=peer;
 elsif parts[3]='pin' then if not orbit_private.circle_mod(cid) then raise exception 'Circle moderator required.' using errcode='42501';end if;pid:=(body->>'post')::bigint;if pid is not null and not exists(select 1 from public.orbit_posts where id=pid and circle=cid and not deleted and orbit_private.can_read(pid)) then raise exception 'Choose an available post from this circle.' using errcode='42501';end if;update public.orbit_circles set pinned_post=pid where id=cid;
 elsif parts[3]='settings' then if circle_row.owner<>u then raise exception 'Owner required.' using errcode='42501';end if;update public.orbit_circles set introduction=coalesce(body->>'introduction',introduction),cover=coalesce(body->>'cover',cover),rules=coalesce(body->>'rules',rules),private=coalesce((body->>'private')::boolean,private) where id=cid;else raise exception 'Invalid circle action.';end if;return '{"ok":true}';end if;end if;
 if path='/notifications' then u:=orbit_private.actor();if method='POST' then update public.orbit_notifications set read=true where actor=u;return '{"ok":true}';end if;select coalesce(jsonb_agg(to_jsonb(n)),'[]') into result from(select n.*,p.handle from public.orbit_notifications n join public.orbit_profiles p on p.id=n.sender where n.actor=u and n.id<before_id and not orbit_private.blocked(u,n.sender) order by n.id desc limit lim)n;return jsonb_build_object('items',result);end if;
 if path='/reports' then u:=orbit_private.actor();if method='GET' then if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select * from public.orbit_reports where id<before_id order by id desc limit lim)r;return jsonb_build_object('items',result);end if;select id into peer from public.orbit_profiles where handle=body->>'target';if peer is null or peer=u then raise exception 'Student unavailable.';end if;insert into public.orbit_reports(reporter,target,reason,details) values(u,peer,body->>'reason',coalesce(body->>'details',''));return '{"ok":true}';end if;
 if parts[1]='reports' and method='POST' then if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;update public.orbit_reports set status=body->>'status' where id=parts[2]::bigint;return '{"ok":true}';end if;
 raise exception 'Endpoint not found.' using errcode='22023';
end;$$;


